def strategy(history, rng):
    if not history:
        return 'C'
    n = len(history)
    # Reciprocate: open with cooperation, then mirror opponent's last move
    last_opponent_move = history[-1][1]
    if last_opponent_move == 'C':
        return 'C'
    else:
        # Opponent defected last round: retaliate, but sometimes forgive to avoid endless DD
        # Probability of forgiveness decreases as defections continue
        consecutive_defections = 0
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'D':
                consecutive_defections += 1
            else:
                break
        # Forgive occasionally, more likely if opponent was mostly cooperative
        if consecutive_defections >= 3:
            # Long defection streak: try a forgiveness move with low probability
            if rng.random() < 0.1:
                return 'C'
        elif consecutive_defections == 2:
            if rng.random() < 0.2:
                return 'C'
        return 'D'

